def open_sidebar_items(apps, schema_editor):
    # Predictions and the league pages are built: the sidebar stops showing them as "soon".
    SidebarItem = apps.get_model("header", "SidebarItem")
    SidebarItem.objects.filter(url="/predictions").update(is_soon=False)
    SidebarItem.objects.filter(url__startswith="/leagues/").update(is_soon=False)


def seed_zones(apps, schema_editor):
    Competition = apps.get_model("sports", "Competition")
    StandingZone = apps.get_model("sports", "StandingZone")
    for competition in Competition.objects.filter(code__in=ZONES):
        for kind, start, end in ZONES[competition.code]:
            StandingZone.objects.get_or_create(
                competition=competition, from_position=start, defaults={"kind": kind, "to_position": end}
            )


